"""Research-only shared DC innovation gate with independent empirical null calibration."""
import numpy as np


def precision_matrix(fields):
    fields = np.asarray(fields, dtype=float)
    if fields.ndim != 3 or fields.shape[1:] != (25, 3) or len(fields) < 2 or not np.isfinite(fields).all():
        raise ValueError('Independent fields with25 finite three-plane innovations required')
    moment = np.einsum('fga,fgb->ab', fields, fields)/(len(fields)*25)
    eigenvalues = np.linalg.eigvalsh(moment)
    if eigenvalues.min() <= 1e-12 or eigenvalues.max()/eigenvalues.min() > 1e8:
        raise ValueError('Ill-conditioned null moment; abstain, do not regularize to fit quality')
    return moment, np.linalg.inv(moment)


def score(innovation, precision):
    innovation = np.asarray(innovation, dtype=float); precision = np.asarray(precision, dtype=float)
    if innovation.shape[-1:] != (3,) or precision.shape != (3, 3) or not all(np.isfinite(x).all() for x in (innovation, precision)):
        raise ValueError('Finite three-plane innovation and precision required')
    return np.maximum(np.einsum('...a,ab,...b->...', innovation, precision, innovation), 0.)


def gain(innovation, calibration):
    threshold = calibration['threshold']
    if not np.isfinite(threshold) or threshold <= 0: raise ValueError('Positive frozen null threshold required')
    value = score(innovation, calibration['precision'])
    return np.maximum(0., 1.-threshold/np.maximum(value, threshold))

